from dataclasses import dataclass

@dataclass(frozen=True)
class TestResult:
    name: str
    status: str
    duration: float

def validate(result):
    if result.status not in {"passed", "failed", "skipped"}:
        raise ValueError("unknown status")
    if result.duration < 0:
        raise ValueError("negative duration")
    return result

